const STORAGE_KEY = 'cloudstudy-progress-v1';
const THEME_KEY = 'cloudstudy-theme-v1';
let currentUnit = 0;
let progress = loadProgress();
const $ = (id) => document.getElementById(id);
const totalTopics = UNITS.reduce((sum,u)=>sum+u.topics.length,0);
const unitColors = {violet:'#a797ff',blue:'#75b7ff',amber:'#ffbd72',cyan:'#62d9ce',rose:'#ff8fa3'};

function loadProgress() {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); } catch { return {}; }
}
function saveProgress() { localStorage.setItem(STORAGE_KEY, JSON.stringify(progress)); }
function keyFor(ui,ti) { return `${UNITS[ui].id}:${ti}`; }
function isDone(ui,ti) { return !!progress[keyFor(ui,ti)]; }
function unitDoneCount(ui) { return UNITS[ui].topics.reduce((n,_,ti)=>n+(isDone(ui,ti)?1:0),0); }
function allDone() { return UNITS.reduce((n,u,ui)=>n+unitDoneCount(ui),0); }
function pct(n,d) { return d ? Math.round(n/d*100) : 0; }

function renderNav() {
  $('unitNav').innerHTML = UNITS.map((u,i)=>{
    const count=unitDoneCount(i), color=unitColors[u.color];
    return `<button class="unit-link ${i===currentUnit?'active':''}" data-unit="${i}" style="--unit-color:${color}">
      <span class="unit-num">${u.number}</span><span><b>${u.title}</b><small>${count} / ${u.topics.length} topics done</small></span>
    </button>`;
  }).join('');
  document.querySelectorAll('.unit-link').forEach(btn=>btn.addEventListener('click',()=>selectUnit(Number(btn.dataset.unit))));
}
function renderUnit() {
  const u=UNITS[currentUnit], color=unitColors[u.color];
  $('unitEyebrow').textContent=`UNIT ${u.number}`;
  $('unitTitle').textContent=u.title;
  $('unitSubtitle').textContent=u.subtitle;
  $('unitTitle').style.color=color;
  renderTopics();
  updateStats();
  renderNav();
  $('prevUnit').disabled=currentUnit===0;
  $('prevUnit').style.opacity=currentUnit===0?'.4':'1';
  $('nextUnit').innerHTML=currentUnit===UNITS.length-1?'Back to Unit 1 <span>↻</span>':'Next unit <span>→</span>';
}
function renderTopics() {
  const u=UNITS[currentUnit], query=$('searchInput').value.trim().toLowerCase(), filter=$('filterSelect').value;
  const matched=u.topics.map((t,i)=>({t,i})).filter(({t,i})=>{
    const done=isDone(currentUnit,i);
    const hay=[t[0],t[1],t[2],...(t[3]||[])].join(' ').toLowerCase();
    return (!query||hay.includes(query))&&(filter==='all'||(filter==='done'?done:!done));
  });
  $('topicSummary').textContent=`Showing ${matched.length} of ${u.topics.length} topics · ${unitDoneCount(currentUnit)} completed`;
  $('topicList').innerHTML=matched.map(({t,i})=>{
    const done=isDone(currentUnit,i);
    return `<details class="topic-card" ${query?'open':''}>
      <summary class="topic-head"><span class="topic-index">${String(i+1).padStart(2,'0')}</span><span class="topic-title">${escapeHtml(t[0])}</span><span class="topic-status ${done?'done':''}">${done?'✓ Completed':'Study topic'}</span><span class="topic-chevron">⌄</span></summary>
      <div class="topic-body"><p>${escapeHtml(t[1])}</p>
        <div class="example-box"><div class="example-label">Real-life example</div><p>${escapeHtml(t[2])}</p></div>
        <div class="keypoints">${(t[3]||[]).map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</div>
        <button class="mark-btn ${done?'is-done':''}" data-topic="${i}">${done?'✓ Marked as completed':'＋ Mark topic as completed'}</button>
      </div></details>`;
  }).join('');
  $('emptyState').classList.toggle('hidden',matched.length!==0);
  document.querySelectorAll('[data-topic]').forEach(btn=>btn.addEventListener('click',()=>{
    const ti=Number(btn.dataset.topic), k=keyFor(currentUnit,ti);
    if(progress[k]) delete progress[k]; else progress[k]=true;
    saveProgress(); renderTopics(); updateStats(); renderNav(); renderRevision();
  }));
  const details=[...document.querySelectorAll('.topic-card')];
  details.forEach(d=>d.addEventListener('toggle',()=>{ if(d.open) details.filter(x=>x!==d).forEach(x=>x.open=false); }));
}
function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
}
function updateStats() {
  const done=allDone(), percent=pct(done,totalTopics), u=UNITS[currentUnit], ud=unitDoneCount(currentUnit), up=pct(ud,u.topics.length);
  $('topicCount').textContent=totalTopics;
  $('doneCount').textContent=done;
  $('percentCount').textContent=percent+'%';
  $('unitProgressText').textContent=up+'%';
  $('unitProgressBar').style.width=up+'%';
}
function renderRevision() {
  const done=allDone(), percent=pct(done,totalTopics);
  $('ringPercent').textContent=percent+'%';
  $('revisionRing').style.background=`conic-gradient(var(--accent) ${percent*3.6}deg,var(--panel3) 0deg)`;
  $('overallBar').style.width=percent+'%';
  $('revisionMessage').textContent=percent===100?'Excellent work — every topic is marked complete. Keep revising the key comparisons and examples.':done?`${done} of ${totalTopics} topics completed. Keep going one topic at a time.`:'Start with Unit 1 and mark topics complete as you go.';
  $('revisionUnits').innerHTML=UNITS.map((u,i)=>{
    const d=unitDoneCount(i), p=pct(d,u.topics.length);
    return `<div class="revision-unit" style="--unit-color:${unitColors[u.color]}"><b>${u.number} · ${u.title}</b><small>${d} / ${u.topics.length} topics · ${p}%</small><div class="mini-track"><span style="width:${p}%"></span></div></div>`;
  }).join('');
}
function selectUnit(i) {
  currentUnit=(i+UNITS.length)%UNITS.length;
  $('searchInput').value=''; $('filterSelect').value='all';
  renderUnit(); document.querySelector('.content-area').scrollIntoView({behavior:'smooth',block:'start'});
}
$('searchInput').addEventListener('input',renderTopics);
$('filterSelect').addEventListener('change',renderTopics);
$('prevUnit').addEventListener('click',()=>selectUnit(currentUnit-1));
$('nextUnit').addEventListener('click',()=>selectUnit(currentUnit+1));
$('continueBtn').addEventListener('click',()=>{
  const first=UNITS.findIndex((u,i)=>unitDoneCount(i)<u.topics.length);
  selectUnit(first<0?0:first);
  const next=UNITS[first<0?0:first].topics.findIndex((_,ti)=>!isDone(first<0?0:first,ti));
  const card=document.querySelectorAll('.topic-card')[Math.max(0,next)];
  if(card){card.open=true;card.scrollIntoView({behavior:'smooth',block:'center'});}
});
$('resetProgress').addEventListener('click',()=>{
  if(confirm('Reset all completed-topic progress?')){progress={};saveProgress();renderUnit();renderRevision();}
});
$('themeToggle').addEventListener('click',()=>{
  document.documentElement.classList.toggle('light');
  localStorage.setItem(THEME_KEY,document.documentElement.classList.contains('light')?'light':'dark');
});
document.addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('searchInput').focus();}
});
if(localStorage.getItem(THEME_KEY)==='light')document.documentElement.classList.add('light');
renderUnit();renderRevision();
